package com.assetflow.notification.controller;
import com.assetflow.notification.response.ApiResponse;import com.assetflow.notification.service.NotificationDataService;import io.jsonwebtoken.Claims;import java.util.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping public class NotificationController {private final NotificationDataService s;public NotificationController(NotificationDataService s){this.s=s;} private Map<String,Object> claims(Authentication a){return ((Claims)a.getPrincipal());}
 @GetMapping("/notification") public ApiResponse<?> list(Authentication a){return ApiResponse.ok(s.notifications(claims(a)));}@PostMapping("/notification") public ApiResponse<?> create(@RequestBody Map<String,Object>b,Authentication a){return ApiResponse.ok(s.createNotification(claims(a),b));}@PutMapping("/notification/read/{id}") public ApiResponse<?> read(@PathVariable long id,Authentication a){s.read(claims(a),id);return ApiResponse.ok(null);}
 @GetMapping("/audit") public ApiResponse<?> audits(Authentication a){return ApiResponse.ok(s.audits(claims(a)));}@PostMapping("/audit") public ApiResponse<?> audit(@RequestBody Map<String,Object>b,Authentication a){return ApiResponse.ok(s.audit(claims(a),b));}@GetMapping("/dashboard") public ApiResponse<?> dashboard(Authentication a){return ApiResponse.ok(s.dashboard(claims(a)));}
 @GetMapping("/report/{type}") public ApiResponse<?> report(@PathVariable String type,Authentication a){return ApiResponse.ok(s.report(type,claims(a)));}@PostMapping("/ai/chat") public ApiResponse<?> chat(@RequestBody Map<String,Object>b,Authentication a){return ApiResponse.ok(s.chat(b));}
}
